def gehe_zu(spot, x, y):
    z = spot.state
    dx, dy = x - z.x, y - z.y
    if math.hypot(dx, dy) < 0.05:
        return                                  # schon da
    richtung = math.degrees(math.atan2(dy, dx))
    spot.move(turn=(richtung - z.heading + 180) % 360 - 180)
    spot.move(forward=math.hypot(dx, dy))

